#include "hash.hpp"
#include <algorithm>
#include <cstring>

namespace digest {
namespace {
constexpr uint32_t start_flag = 1;
constexpr uint32_t end_flag = 2;
constexpr uint32_t parent_flag = 4;
constexpr uint32_t root_flag = 8;

uint32_t rotate(uint32_t x, unsigned n) {
    return (x >> n) | (x << (32 - n));
}

void mix(Words16 &v, int a, int b, int c, int d, uint32_t x, uint32_t y) {
    v[a] += v[b] + x;
    v[d] = rotate(v[d] ^ v[a], 16);
    v[c] += v[d];
    v[b] = rotate(v[b] ^ v[c], 12);
    v[a] += v[b] + y;
    v[d] = rotate(v[d] ^ v[a], 8);
    v[c] += v[d];
    v[b] = rotate(v[b] ^ v[c], 7);
}

Words16 compress(const Words8 &input, Words16 message, uint64_t counter,
                 uint32_t length, uint32_t flags) {
    Words16 v{};
    std::copy(input.begin(), input.end(), v.begin());
    std::copy_n(initial_words.begin(), 4, v.begin() + 8);
    v[12] = static_cast<uint32_t>(counter);
    v[13] = static_cast<uint32_t>(counter >> 32);
    v[14] = length;
    v[15] = flags;
    constexpr int shuffle[16] = {2, 6, 3, 10, 7, 0, 4, 13, 1, 11, 12, 5, 9, 14, 15, 8};
    for (int round = 0; round < 7; ++round) {
        mix(v, 0, 4, 8, 12, message[0], message[1]);
        mix(v, 1, 5, 9, 13, message[2], message[3]);
        mix(v, 2, 6, 10, 14, message[4], message[5]);
        mix(v, 3, 7, 11, 15, message[6], message[7]);
        mix(v, 0, 5, 10, 15, message[8], message[9]);
        mix(v, 1, 6, 11, 12, message[10], message[11]);
        mix(v, 2, 7, 8, 13, message[12], message[13]);
        mix(v, 3, 4, 9, 14, message[14], message[15]);
        Words16 next{};
        for (int j = 0; j < 16; ++j) next[j] = message[shuffle[j]];
        message = next;
    }
    for (int j = 0; j < 8; ++j) {
        v[j] ^= v[j + 8];
        v[j + 8] ^= input[j];
    }
    return v;
}
}

Words8 decode_key(const uint8_t *bytes) {
    Words8 words{};
    for (size_t i = 0; i < 32; ++i)
        words[i / 4] |= uint32_t(bytes[i]) << (8 * (i % 4));
    return words;
}

Words8 Node::chaining() const {
    auto result = compress(input, block, counter, length, flags);
    Words8 out;
    std::copy_n(result.begin(), 8, out.begin());
    return out;
}

std::array<uint8_t, 64> Node::output_block(uint64_t number) const {
    auto words = compress(input, block, number, length, flags | root_flag);
    std::array<uint8_t, 64> bytes;
    for (size_t i = 0; i < bytes.size(); ++i)
        bytes[i] = static_cast<uint8_t>(words[i / 4] >> (8 * (i % 4)));
    return bytes;
}

void Node::output(uint64_t first_byte, uint8_t *destination, size_t count) const {
    uint64_t number = first_byte / 64;
    size_t skip = first_byte % 64;
    while (count) {
        auto bytes = output_block(number++);
        size_t n = std::min(count, 64 - skip);
        std::memcpy(destination, bytes.data() + skip, n);
        destination += n;
        count -= n;
        skip = 0;
    }
}

Node Hasher::chunk_node() const {
    Words8 chaining = key_;
    size_t position = 0;
    for (;;) {
        size_t n = std::min(size_t(64), used_ - position);
        uint32_t flags = mode_;
        if (position == 0) flags |= start_flag;
        if (position + n == used_) flags |= end_flag;
        Words16 block{};
        for (size_t j = 0; j < n; ++j)
            block[j / 4] |= uint32_t(chunk_[position + j]) << (8 * (j % 4));
        Node node{chaining, block, completed_, static_cast<uint32_t>(n), flags};
        if (flags & end_flag) return node;
        chaining = node.chaining();
        position += n;
    }
}

Node Hasher::parent(const Words8 &left, const Words8 &right) const {
    Words16 block;
    std::copy(left.begin(), left.end(), block.begin());
    std::copy(right.begin(), right.end(), block.begin() + 8);
    return {key_, block, 0, 64, mode_ | parent_flag};
}

void Hasher::commit_chunk() {
    Words8 current = chunk_node().chaining();
    uint64_t total = ++completed_;
    while ((total & 1) == 0) {
        current = parent(tree_.back(), current).chaining();
        tree_.pop_back();
        total >>= 1;
    }
    tree_.push_back(current);
    used_ = 0;
}

void Hasher::update(const uint8_t *data, size_t size) {
    while (size) {
        if (used_ == chunk_.size()) commit_chunk();
        size_t n = std::min(size, chunk_.size() - used_);
        std::memcpy(chunk_.data() + used_, data, n);
        used_ += n;
        data += n;
        size -= n;
    }
}

Node Hasher::finish() const {
    Node node = chunk_node();
    for (auto it = tree_.rbegin(); it != tree_.rend(); ++it)
        node = parent(*it, node.chaining());
    return node;
}
}
EOF
