        if (options.empty() && !required_files && fallback) result += " [OPTIONS]";
        for (int id : options) result += " " + option_label(id);
        result += required_files ? " <FILE>...\n" : " [FILE]...\n";
        return result;
    }

    [[noreturn]] void error(const string &detail, const string &use = "") const {
        put_err("error: " + detail + "\n" + (use.empty() ? "" : "\n" + use) + more_information);
        throw Exit{2};
    }

    // The spelling hint is chosen by matching characters and their order, not
    // by accepting prefixes as aliases. Abbreviated flags are still errors.
    static double similarity(const string &a, const string &b) {
        if (a == b) return 1;
        if (a.empty() || b.empty()) return 0;
        int reach = std::max(int(std::max(a.size(), b.size()) / 2) - 1, 0);
        std::vector<bool> used_a(a.size()), used_b(b.size());
        int count = 0;
        for (int i = 0; i < int(a.size()); ++i) {
            int end = std::min(int(b.size()), i + reach + 1);
            for (int j = std::max(0, i - reach); j < end; ++j) {
                if (!used_b[j] && a[i] == b[j]) {
                    used_a[i] = used_b[j] = true;
                    ++count;
                    break;
                }
