        if (!count) return 0;
        int different = 0, j = 0;
        for (size_t i = 0; i < a.size(); ++i) {
            if (!used_a[i]) continue;
            while (!used_b[j]) ++j;
            if (a[i] != b[j]) ++different;
            ++j;
        }
        double m = count;
        return (m / a.size() + m / b.size() + (m - different / 2.0) / m) / 3.0;
    }

