        string detail = "unexpected argument '" + display_string(arg) + "' found\n\n  tip: ";
        if (suggestion >= 0) {
            detail += "a similar argument exists: '--" + string(specs[suggestion].name) + "'";
            if (std::find(used.begin(), used.end(), suggestion) == used.end())
