    static int short_id(char c) {
        for (int i = 0; i < OPTION_COUNT; ++i) if (specs[i].short_name && c == specs[i].short_name) return i;
        return -1;
    }

    string next_value(int id, int &i, int argc, char **argv) {
        if (i + 1 == argc) missing(id);
        string next = argv[i + 1];
        if (next.size() > 1 && next[0] == '-') {
            bool known = next == "--" || (next[1] == '-' ? long_id(next) >= 0 : short_id(next[1]) >= 0);
            if (known) missing(id);
            if (next[1] == '-') unexpected(next);
            unexpected(next.substr(0, 2));
