            if (need_check) order.insert(order.begin(), CHECK);
            error(detail, usage(order, need_files || !options_.files.empty()));
        }
    }

public:
    explicit Parser(string program_name) : name_(std::move(program_name)) {}

    Options parse(int argc, char **argv) {
        bool positional_only = false;
        for (int i = 1; i < argc; ++i) {
            string arg = argv[i];
            if (!positional_only && arg == "--") { positional_only = true; continue; }
            if (!positional_only && arg.size() > 1 && arg[0] == '-') {
