struct FileCloser { void operator()(FILE *f) const { if (f) std::fclose(f); } };
using FileOwner = std::unique_ptr<FILE, FileCloser>;

FILE *open_input(const string &name, FileOwner &owned, bool keyed = false) {
    if (name == "-") {
        if (keyed) throw std::runtime_error("Cannot open `-` in keyed mode");
        return stdin;
    }
    FILE *f = std::fopen(name.c_str(), "rb");
    if (!f) throw std::runtime_error(os_error(errno));
    owned.reset(f);
    return f;
}

void add_file(digest::Hasher &hasher, FILE *f) {
    std::array<uint8_t, 65536> buffer;
    for (;;) {
        size_t count = std::fread(buffer.data(), 1, buffer.size(), f);
        if (count) hasher.update(buffer.data(), count);
        if (count != buffer.size()) {
            if (std::ferror(f)) {
                if (errno == EINTR) { std::clearerr(f); continue; }
                throw std::runtime_error(os_error(errno));
            }
            if (std::feof(f)) break;
        }
    }
}

struct Mode {
    digest::Words8 key = digest::initial_words;
    uint32_t flags = 0;
};

Mode select_mode(const Options &options) {
    Mode mode;
    if (options.present[KEYED]) {
        std::array<uint8_t, 33> bytes;
        size_t count = std::fread(bytes.data(), 1, bytes.size(), stdin);
        if (std::ferror(stdin)) throw std::runtime_error(os_error(errno));
        if (count < 32) throw std::runtime_error("expected 32 key bytes from stdin, found " + std::to_string(count));
        if (count > 32) throw std::runtime_error("read more than 32 key bytes from stdin");
        mode.key = digest::decode_key(bytes.data());
        mode.flags = digest::keyed;
    } else if (options.present[DERIVE]) {
        digest::Hasher hash(digest::initial_words, digest::context);
        hash.update(reinterpret_cast<const uint8_t *>(options.context.data()), options.context.size());
        std::array<uint8_t, 32> context_key;
        hash.finish().output(0, context_key.data(), context_key.size());
        mode.key = digest::decode_key(context_key.data());
        mode.flags = digest::material;
    }
    return mode;
}

string hex(const uint8_t *data, size_t size) {
    static const char digits[] = "0123456789abcdef";
    string encoded(size * 2, '0');
    for (size_t i = 0; i < size; ++i) {
        encoded[2 * i] = digits[data[i] >> 4];
        encoded[2 * i + 1] = digits[data[i] & 15];
    }
    return encoded;
}

std::pair<bool, string> escape_path(const string &name) {
    bool needs_escape = false;
    string out;
    for (char c : display_string(name)) {
        switch (c) {
        case '\\': out += "\\\\"; needs_escape = true; break;
        case '\n': out += "\\n"; needs_escape = true; break;
        case '\r': out += "\\r"; needs_escape = true; break;
        default: out += c;
        }
    }
    return {needs_escape, std::move(out)};
}

void write_digest(const digest::Node &node, const Options &options, const string &path) {
    bool raw = options.present[RAW];
    bool names = !raw && !options.present[NO_NAMES];
    bool tag = options.present[TAG];
    auto escaped = names ? escape_path(path) : std::pair<bool, string>{false, {}};
    if (names) {
        if (escaped.first) put_out("\\");
        if (tag) put_out("BLAKE3 (" + escaped.second + ") = ");
    }
    uint64_t number = options.seek / 64;
    size_t skip = options.seek % 64;
    uint64_t remaining = options.length;
    while (remaining) {
        auto bytes = node.output_block(number++);
        size_t n = size_t(std::min(remaining, uint64_t(64 - skip)));
        if (raw) write_bytes(stdout, bytes.data() + skip, n);
        else put_out(hex(bytes.data() + skip, n));
        remaining -= n;
        skip = 0;
    }
    if (!raw) {
        if (names && !tag) put_out("  " + escaped.second);
        put_out("\n");
    }
}

struct CheckLine {
    string actual_path;
    string printed_path;
    std::array<uint8_t, 32> expected;
};

CheckLine parse_check_line(string line) {
    while (!line.empty() && (line.back() == '\r' || line.back() == '\n')) line.pop_back();
    if (line.empty()) throw std::runtime_error("Empty line");
    bool escaped = line[0] == '\\';
    if (escaped) line.erase(0, 1);
    string hash, path;
    size_t delimiter = line.find("  ");
    if (delimiter != string::npos) {
        hash = line.substr(0, delimiter);
        path = line.substr(delimiter + 2);
    } else {
        size_t end = line.rfind(") = ");
        if (line.compare(0, 8, "BLAKE3 (") != 0 || end == string::npos || end < 8)
            throw std::runtime_error("Invalid check line format");
        path = line.substr(8, end - 8);
        hash = line.substr(end + 4);
    }
    if (hash.size() != 64) throw std::runtime_error("Invalid hash length");
    CheckLine parsed;
    parsed.printed_path = (escaped ? "\\" : "") + path;
    for (size_t i = 0; i < 32; ++i) {
        unsigned byte = 0;
        for (size_t j = 0; j < 2; ++j) {
            char c = hash[2 * i + j];
            int digit = c >= '0' && c <= '9' ? c - '0' : c >= 'a' && c <= 'f' ? c - 'a' + 10 : -1;
            if (digit < 0) throw std::runtime_error("Invalid hex");
            byte = byte * 16 + digit;
        }
        parsed.expected[i] = static_cast<uint8_t>(byte);
    }
    if (escaped) {
        for (size_t i = 0; i < path.size(); ++i) {
            if (path[i] != '\\') parsed.actual_path += path[i];
            else {
                if (++i == path.size()) throw std::runtime_error("Invalid backslash escape");
                if (path[i] == '\\') parsed.actual_path += '\\';
                else if (path[i] == 'n') parsed.actual_path += '\n';
                else if (path[i] == 'r') parsed.actual_path += '\r';
                else throw std::runtime_error("Invalid backslash escape");
            }
        }
    } else parsed.actual_path = path;
    if (parsed.actual_path.empty()) throw std::runtime_error("empty file path");
    if (parsed.actual_path.find('\0') != string::npos) throw std::runtime_error("Null character in path");
    if (parsed.actual_path.find("\xef\xbf\xbd") != string::npos) throw std::runtime_error("Unicode replacement character in path");
    return parsed;
}

bool check_one(const CheckLine &line, const Options &options) {
    bool success = false;
    string error;
    try {
        FileOwner owner;
        FILE *f = open_input(line.actual_path, owner);
        digest::Hasher hasher;
        add_file(hasher, f);
        std::array<uint8_t, 32> actual;
        hasher.finish().output(options.seek, actual.data(), actual.size());
        success = actual == line.expected;
    } catch (const std::exception &e) { error = e.what(); }
    if (!success || !options.present[QUIET]) {
        string status = success ? "OK" : "FAILED";
        if (!error.empty()) status += " (" + error + ")";
        put_out(line.printed_path + ": " + status + "\n");
    }
    return success;
}

int check_files(const Options &options) {
    uint64_t failures = 0;
    for (const string &name : options.files) {
        FileOwner owner;
        FILE *f = open_input(name, owner);
        char *buffer = nullptr;
        size_t capacity = 0;
        for (;;) {
            errno = 0;
            ssize_t n = ::getline(&buffer, &capacity, f);
            if (n < 0) {
                std::free(buffer);
                buffer = nullptr;
                if (std::ferror(f)) throw std::runtime_error(os_error(errno));
                break;
            }
            string line(buffer, size_t(n));
            if (!valid_utf8(line)) {
                std::free(buffer);
                throw std::runtime_error("stream did not contain valid UTF-8");
            }
            std::optional<CheckLine> parsed;
            try { parsed = parse_check_line(std::move(line)); }
            catch (const std::exception &e) {
                put_err("b3sum: " + string(e.what()) + "\n");
                ++failures;
                continue;
            }
            if (!check_one(*parsed, options)) ++failures;
        }
    }
    if (failures) {
        put_err("b3sum: WARNING: " + std::to_string(failures) + " computed checksum" +
                (failures == 1 ? "" : "s") + " did NOT match\n");
        return 1;
    }
    return 0;
}

int run(Options options) {
    if (options.present[RAW] && options.files.size() > 1)
        throw std::runtime_error("Only one filename can be provided when using --raw");
    Mode mode = select_mode(options);
    if (options.files.empty()) options.files.emplace_back("-");
    if (options.present[CHECK]) return check_files(options);
    int result = 0;
    for (const string &path : options.files) {
        try {
            FileOwner owner;
            FILE *f = open_input(path, owner, options.present[KEYED]);
            digest::Hasher hasher(mode.key, mode.flags);
            add_file(hasher, f);
            write_digest(hasher.finish(), options, path);
        } catch (const std::exception &e) {
            put_err("b3sum: " + display_string(path) + ": " + e.what() + "\n");
            result = 1;
        }
    }
    return result;
}
}

int main(int argc, char **argv) {
    std::signal(SIGPIPE, SIG_IGN);
    string name = argc && argv[0] ? argv[0] : "executable";
    size_t slash = name.rfind('/');
    if (slash != string::npos) name.erase(0, slash + 1);
    name = display_string(name);
    int status = 0;
    try {
        Parser parser(name);
        status = run(parser.parse(argc, argv));
    } catch (Exit e) { status = e.status; }
    catch (const std::exception &e) {
        put_err("Error: " + string(e.what()) + "\n");
        status = 1;
    }
    std::fflush(stdout);
    return status;
}
