#include "hash.hpp"
#include "help.hpp"

#include <algorithm>
#include <array>
#include <cerrno>
#include <csignal>
#include <cstdio>
#include <cstdlib>
#include <cstring>
#include <limits>
#include <memory>
#include <optional>
#include <stdexcept>
#include <string>
#include <utility>
#include <vector>
#include <unistd.h>

namespace {
using std::string;

struct Exit { int status; };

string os_error(int number) {
    return string(std::strerror(number)) + " (os error " + std::to_string(number) + ")";
}

// Walk UTF-8 without relying on the locale. Invalid argument filenames remain
// usable on Unix, but their display follows the replacement-character convention.
size_t utf8_sequence(const string &s, size_t at, bool &valid) {
    unsigned char first = s[at];
    valid = true;
    if (first < 0x80) return 1;
    unsigned n = first >= 0xc2 && first <= 0xdf ? 2 :
                 first >= 0xe0 && first <= 0xef ? 3 :
                 first >= 0xf0 && first <= 0xf4 ? 4 : 0;
    if (!n) { valid = false; return 1; }
    for (unsigned j = 1; j < n; ++j) {
        if (at + j >= s.size()) { valid = false; return j; }
        unsigned char c = s[at + j];
        bool ok = c >= 0x80 && c <= 0xbf;
        if (j == 1) {
            if (first == 0xe0) ok = c >= 0xa0 && c <= 0xbf;
            if (first == 0xed) ok = c >= 0x80 && c <= 0x9f;
            if (first == 0xf0) ok = c >= 0x90 && c <= 0xbf;
            if (first == 0xf4) ok = c >= 0x80 && c <= 0x8f;
        }
        if (!ok) { valid = false; return j; }
    }
    return n;
}

bool valid_utf8(const string &s) {
    for (size_t i = 0; i < s.size();) {
        bool valid;
        i += utf8_sequence(s, i, valid);
        if (!valid) return false;
    }
    return true;
}

string display_string(const string &s) {
    string out;
    for (size_t i = 0; i < s.size();) {
        bool valid;
        size_t n = utf8_sequence(s, i, valid);
        if (valid) out.append(s, i, n);
        else out += "\xef\xbf\xbd";
        i += n;
    }
    return out;
}

void write_bytes(FILE *to, const void *data, size_t size) {
    if (size && std::fwrite(data, 1, size, to) != size)
        throw std::runtime_error(os_error(errno));
}
void put_out(const string &s) { write_bytes(stdout, s.data(), s.size()); }
void put_err(const string &s) { std::fwrite(s.data(), 1, s.size(), stderr); }

const string more_information = "\nFor more information, try '--help'.\n";

enum Option { KEYED, DERIVE, LENGTH, SEEK, THREADS, NO_MMAP, NO_NAMES,
              RAW, TAG, CHECK, QUIET, HELP, VERSION, OPTION_COUNT };
struct Specification { const char *name; const char *parameter; char short_name; };
constexpr Specification specs[OPTION_COUNT] = {
    {"keyed", nullptr, 0}, {"derive-key", "CONTEXT", 0},
    {"length", "LEN", 'l'}, {"seek", "SEEK", 0},
    {"num-threads", "NUM", 0}, {"no-mmap", nullptr, 0},
    {"no-names", nullptr, 0}, {"raw", nullptr, 0},
    {"tag", nullptr, 0}, {"check", nullptr, 'c'},
    {"quiet", nullptr, 0}, {"help", nullptr, 'h'},
    {"version", nullptr, 'V'}
};

string option_label(int id) {
    string result = string("--") + specs[id].name;
    if (specs[id].parameter) result += " <" + string(specs[id].parameter) + ">";
    return result;
}

bool clashes(int a, int b) {
    if (a == b) return false;
    if ((a == KEYED && b == DERIVE) || (b == KEYED && a == DERIVE)) return true;
    if (b == CHECK) std::swap(a, b);
    return a == CHECK && (b == KEYED || b == DERIVE || b == LENGTH ||
                          b == NO_NAMES || b == RAW || b == TAG);
}

struct Options {
    std::array<bool, OPTION_COUNT> present{};
    std::vector<int> order;
    std::vector<string> files;
    string context;
    uint64_t length = 32;
    uint64_t seek = 0;
    uint64_t threads = 0;
};

class Parser {
    string name_;
    Options options_;

    string generic_usage() const { return "Usage: " + name_ + " [OPTIONS] [FILE]...\n"; }

    string usage(const std::vector<int> &options, bool required_files,
                 bool fallback = true) const {
        string result = "Usage: " + name_;
        if (options.empty() && !required_files && fallback) result += " [OPTIONS]";
        for (int id : options) result += " " + option_label(id);
        result += required_files ? " <FILE>...\n" : " [FILE]...\n";
        return result;
    }

    [[noreturn]] void error(const string &detail, const string &use = "") const {
        put_err("error: " + detail + "\n" + (use.empty() ? "" : "\n" + use) + more_information);
        throw Exit{2};
    }

    // The spelling hint is chosen by matching characters and their order, not
    // by accepting prefixes as aliases. Abbreviated flags are still errors.
    static double similarity(const string &a, const string &b) {
        if (a == b) return 1;
        if (a.empty() || b.empty()) return 0;
        int reach = std::max(int(std::max(a.size(), b.size()) / 2) - 1, 0);
        std::vector<bool> used_a(a.size()), used_b(b.size());
        int count = 0;
        for (int i = 0; i < int(a.size()); ++i) {
            int end = std::min(int(b.size()), i + reach + 1);
            for (int j = std::max(0, i - reach); j < end; ++j) {
                if (!used_b[j] && a[i] == b[j]) {
                    used_a[i] = used_b[j] = true;
                    ++count;
                    break;
                }
            }
        }
        if (!count) return 0;
        int different = 0, j = 0;
        for (size_t i = 0; i < a.size(); ++i) {
            if (!used_a[i]) continue;
            while (!used_b[j]) ++j;
            if (a[i] != b[j]) ++different;
            ++j;
        }
        double m = count;
        return (m / a.size() + m / b.size() + (m - different / 2.0) / m) / 3.0;
    }

    [[noreturn]] void unexpected(string arg) const {
        auto used = options_.order;
        int suggestion = -1;
        double highest = 0.7;
        if (arg.compare(0, 2, "--") == 0) {
            arg = arg.substr(0, arg.find('='));
            for (int id = 0; id < OPTION_COUNT; ++id) {
                double score = similarity(arg.substr(2), specs[id].name);
                if (score > highest) { highest = score; suggestion = id; }
            }
        }
        string detail = "unexpected argument '" + display_string(arg) + "' found\n\n  tip: ";
        if (suggestion >= 0) {
            detail += "a similar argument exists: '--" + string(specs[suggestion].name) + "'";
            if (std::find(used.begin(), used.end(), suggestion) == used.end())
                used.push_back(suggestion);
        } else {
            detail += "to pass '" + display_string(arg) + "' as a value, use '-- " + display_string(arg) + "'";
        }
        error(detail, usage(used, !options_.files.empty()));
    }

    [[noreturn]] void missing(int id) const {
        error("a value is required for '" + option_label(id) + "' but none was supplied");
    }

    [[noreturn]] void duplicate(int id) const {
        error("the argument '" + option_label(id) + "' cannot be used multiple times", generic_usage());
    }

    [[noreturn]] void unexpected_value(int id, const string &value) const {
        bool has_boolean = false;
        for (int seen : options_.order) if (!specs[seen].parameter) has_boolean = true;
        string use;
        if (has_boolean) {
            use = "Usage: " + name_ + " <FILE";
            for (int i = 0; i <= QUIET; ++i) use += "|" + option_label(i);
            use += ">\n";
        } else {
            use = usage({id}, false);
        }
        error("unexpected value '" + display_string(value) + "' for '--" + specs[id].name +
              "' found; no more were expected", use);
    }

    uint64_t number(int id, const string &s) const {
        string reason;
        uint64_t value = 0;
        if (s.empty()) reason = "cannot parse integer from empty string";
        size_t from = !s.empty() && s[0] == '+' ? 1 : 0;
        if (from == s.size() && !s.empty()) reason = "invalid digit found in string";
        for (size_t i = from; i < s.size() && reason.empty(); ++i) {
            unsigned char c = s[i];
            if (c < '0' || c > '9') { reason = "invalid digit found in string"; break; }
            unsigned digit = c - '0';
            if (value > (std::numeric_limits<uint64_t>::max() - digit) / 10) {
                reason = "number too large to fit in target type";
                break;
            }
            value = value * 10 + digit;
        }
        if (!reason.empty())
            error("invalid value '" + display_string(s) + "' for '" + option_label(id) + "': " + reason);
        return value;
    }

    static int long_id(const string &arg) {
        string name = arg.substr(2, arg.find('=') == string::npos ? string::npos : arg.find('=') - 2);
        for (int i = 0; i < OPTION_COUNT; ++i) if (name == specs[i].name) return i;
        return -1;
    }
    static int short_id(char c) {
        for (int i = 0; i < OPTION_COUNT; ++i) if (specs[i].short_name && c == specs[i].short_name) return i;
        return -1;
    }

    string next_value(int id, int &i, int argc, char **argv) {
        if (i + 1 == argc) missing(id);
        string next = argv[i + 1];
        if (next.size() > 1 && next[0] == '-') {
            bool known = next == "--" || (next[1] == '-' ? long_id(next) >= 0 : short_id(next[1]) >= 0);
            if (known) missing(id);
            if (next[1] == '-') unexpected(next);
            unexpected(next.substr(0, 2));
        }
        ++i;
        return next;
    }

    void accept(int id, const string &value, bool long_form) {
        if (options_.present[id]) duplicate(id);
        if (id == HELP) {
            put_out("Usage: " + name_ + (long_form ? long_help : short_help));
            throw Exit{0};
        }
        if (id == VERSION) { put_out("b3sum 1.8.4\n"); throw Exit{0}; }
        if (id == LENGTH) options_.length = number(id, value);
        if (id == SEEK) options_.seek = number(id, value);
        if (id == THREADS) options_.threads = number(id, value);
        if (id == DERIVE) {
            if (!valid_utf8(value)) error("invalid UTF-8 was detected in one or more arguments", generic_usage());
            options_.context = value;
        }
        options_.present[id] = true;
        options_.order.push_back(id);
    }

    void validate() const {
        for (int id : options_.order) {
            std::vector<int> conflicts, retained;
            for (int other : options_.order) {
                if (clashes(id, other)) conflicts.push_back(other);
                else retained.push_back(other);
            }
            if (conflicts.empty()) continue;
            string detail = "the argument '" + option_label(id) + "' cannot be used with";
            if (conflicts.size() == 1) detail += " '" + option_label(conflicts[0]) + "'";
            else {
                detail += ":";
                for (int other : conflicts) detail += "\n  " + option_label(other);
            }
            bool required = !options_.files.empty() || std::find(retained.begin(), retained.end(), KEYED) != retained.end();
            error(detail, usage(retained, required));
        }
        bool need_files = options_.present[KEYED] && options_.files.empty();
        bool check_suppressed = false;
        for (int id : options_.order) if (clashes(id, CHECK)) check_suppressed = true;
        bool need_check = options_.present[QUIET] && !options_.present[CHECK] && (!check_suppressed || need_files);
        if (need_files || need_check) {
            string detail = "the following required arguments were not provided:";
            if (need_check) detail += "\n  --check";
            if (need_files) detail += "\n  <FILE>...";
            auto order = options_.order;
            if (need_check) order.insert(order.begin(), CHECK);
            error(detail, usage(order, need_files || !options_.files.empty()));
        }
    }

public:
    explicit Parser(string program_name) : name_(std::move(program_name)) {}

    Options parse(int argc, char **argv) {
        bool positional_only = false;
        for (int i = 1; i < argc; ++i) {
            string arg = argv[i];
            if (!positional_only && arg == "--") { positional_only = true; continue; }
            if (!positional_only && arg.size() > 1 && arg[0] == '-') {
                if (arg[1] == '-') {
                    int id = long_id(arg);
                    if (id < 0) unexpected(arg);
                    size_t equal = arg.find('=');
                    if (!specs[id].parameter && equal != string::npos)
                        unexpected_value(id, arg.substr(equal + 1));
                    if (options_.present[id]) duplicate(id);
                    string value;
                    if (specs[id].parameter)
                        value = equal == string::npos ? next_value(id, i, argc, argv) : arg.substr(equal + 1);
                    accept(id, value, true);
                } else {
                    // A cluster is committed as one token, so an unknown short
                    // flag does not enter partially parsed flags in the usage.
                    Options before = options_;
                    for (size_t j = 1; j < arg.size(); ++j) {
                        int id = short_id(arg[j]);
                        if (id < 0) {
                            options_ = before;
                            unexpected(string("-") + arg[j]);
                        }
                        if (options_.present[id]) duplicate(id);
                        string value;
                        if (specs[id].parameter) {
                            if (j + 1 < arg.size()) {
                                value = arg.substr(j + 1);
                                if (value[0] == '=') value.erase(0, 1);
                            } else value = next_value(id, i, argc, argv);
                            j = arg.size();
                        }
                        accept(id, value, false);
                    }
                }
            } else {
                if (arg.empty()) error("a value is required for '[FILE]...' but none was supplied");
                options_.files.push_back(std::move(arg));
            }
        }
        validate();
        return options_;
    }
};

struct FileCloser { void operator()(FILE *f) const { if (f) std::fclose(f); } };
using FileOwner = std::unique_ptr<FILE, FileCloser>;

FILE *open_input(const string &name, FileOwner &owned, bool keyed = false) {
    if (name == "-") {
        if (keyed) throw std::runtime_error("Cannot open `-` in keyed mode");
        return stdin;
    }
    FILE *f = std::fopen(name.c_str(), "rb");
    if (!f) throw std::runtime_error(os_error(errno));
    owned.reset(f);
    return f;
}

void add_file(digest::Hasher &hasher, FILE *f) {
    std::array<uint8_t, 65536> buffer;
    for (;;) {
        size_t count = std::fread(buffer.data(), 1, buffer.size(), f);
        if (count) hasher.update(buffer.data(), count);
        if (count != buffer.size()) {
            if (std::ferror(f)) {
                if (errno == EINTR) { std::clearerr(f); continue; }
                throw std::runtime_error(os_error(errno));
            }
            if (std::feof(f)) break;
        }
    }
}

struct Mode {
    digest::Words8 key = digest::initial_words;
    uint32_t flags = 0;
};

Mode select_mode(const Options &options) {
    Mode mode;
    if (options.present[KEYED]) {
        std::array<uint8_t, 33> bytes;
        size_t count = std::fread(bytes.data(), 1, bytes.size(), stdin);
        if (std::ferror(stdin)) throw std::runtime_error(os_error(errno));
        if (count < 32) throw std::runtime_error("expected 32 key bytes from stdin, found " + std::to_string(count));
        if (count > 32) throw std::runtime_error("read more than 32 key bytes from stdin");
        mode.key = digest::decode_key(bytes.data());
        mode.flags = digest::keyed;
    } else if (options.present[DERIVE]) {
        digest::Hasher hash(digest::initial_words, digest::context);
        hash.update(reinterpret_cast<const uint8_t *>(options.context.data()), options.context.size());
        std::array<uint8_t, 32> context_key;
        hash.finish().output(0, context_key.data(), context_key.size());
        mode.key = digest::decode_key(context_key.data());
        mode.flags = digest::material;
    }
    return mode;
}

string hex(const uint8_t *data, size_t size) {
    static const char digits[] = "0123456789abcdef";
    string encoded(size * 2, '0');
    for (size_t i = 0; i < size; ++i) {
        encoded[2 * i] = digits[data[i] >> 4];
        encoded[2 * i + 1] = digits[data[i] & 15];
    }
    return encoded;
}

std::pair<bool, string> escape_path(const string &name) {
    bool needs_escape = false;
    string out;
    for (char c : display_string(name)) {
        switch (c) {
        case '\\': out += "\\\\"; needs_escape = true; break;
        case '\n': out += "\\n"; needs_escape = true; break;
        case '\r': out += "\\r"; needs_escape = true; break;
        default: out += c;
        }
    }
    return {needs_escape, std::move(out)};
}

void write_digest(const digest::Node &node, const Options &options, const string &path) {
    bool raw = options.present[RAW];
    bool names = !raw && !options.present[NO_NAMES];
    bool tag = options.present[TAG];
    auto escaped = names ? escape_path(path) : std::pair<bool, string>{false, {}};
    if (names) {
        if (escaped.first) put_out("\\");
        if (tag) put_out("BLAKE3 (" + escaped.second + ") = ");
    }
    uint64_t number = options.seek / 64;
    size_t skip = options.seek % 64;
    uint64_t remaining = options.length;
    while (remaining) {
        auto bytes = node.output_block(number++);
        size_t n = size_t(std::min(remaining, uint64_t(64 - skip)));
        if (raw) write_bytes(stdout, bytes.data() + skip, n);
        else put_out(hex(bytes.data() + skip, n));
        remaining -= n;
        skip = 0;
    }
    if (!raw) {
        if (names && !tag) put_out("  " + escaped.second);
        put_out("\n");
    }
}

struct CheckLine {
    string actual_path;
    string printed_path;
    std::array<uint8_t, 32> expected;
};

CheckLine parse_check_line(string line) {
    while (!line.empty() && (line.back() == '\r' || line.back() == '\n')) line.pop_back();
    if (line.empty()) throw std::runtime_error("Empty line");
    bool escaped = line[0] == '\\';
    if (escaped) line.erase(0, 1);
    string hash, path;
    size_t delimiter = line.find("  ");
    if (delimiter != string::npos) {
        hash = line.substr(0, delimiter);
        path = line.substr(delimiter + 2);
    } else {
        size_t end = line.rfind(") = ");
        if (line.compare(0, 8, "BLAKE3 (") != 0 || end == string::npos || end < 8)
            throw std::runtime_error("Invalid check line format");
        path = line.substr(8, end - 8);
        hash = line.substr(end + 4);
    }
    if (hash.size() != 64) throw std::runtime_error("Invalid hash length");
    CheckLine parsed;
    parsed.printed_path = (escaped ? "\\" : "") + path;
    for (size_t i = 0; i < 32; ++i) {
        unsigned byte = 0;
        for (size_t j = 0; j < 2; ++j) {
            char c = hash[2 * i + j];
            int digit = c >= '0' && c <= '9' ? c - '0' : c >= 'a' && c <= 'f' ? c - 'a' + 10 : -1;
            if (digit < 0) throw std::runtime_error("Invalid hex");
            byte = byte * 16 + digit;
        }
        parsed.expected[i] = static_cast<uint8_t>(byte);
    }
    if (escaped) {
        for (size_t i = 0; i < path.size(); ++i) {
            if (path[i] != '\\') parsed.actual_path += path[i];
            else {
                if (++i == path.size()) throw std::runtime_error("Invalid backslash escape");
                if (path[i] == '\\') parsed.actual_path += '\\';
                else if (path[i] == 'n') parsed.actual_path += '\n';
                else if (path[i] == 'r') parsed.actual_path += '\r';
                else throw std::runtime_error("Invalid backslash escape");
            }
        }
    } else parsed.actual_path = path;
    if (parsed.actual_path.empty()) throw std::runtime_error("empty file path");
    if (parsed.actual_path.find('\0') != string::npos) throw std::runtime_error("Null character in path");
    if (parsed.actual_path.find("\xef\xbf\xbd") != string::npos) throw std::runtime_error("Unicode replacement character in path");
    return parsed;
}

bool check_one(const CheckLine &line, const Options &options) {
    bool success = false;
    string error;
    try {
        FileOwner owner;
        FILE *f = open_input(line.actual_path, owner);
        digest::Hasher hasher;
        add_file(hasher, f);
        std::array<uint8_t, 32> actual;
        hasher.finish().output(options.seek, actual.data(), actual.size());
        success = actual == line.expected;
    } catch (const std::exception &e) { error = e.what(); }
    if (!success || !options.present[QUIET]) {
        string status = success ? "OK" : "FAILED";
        if (!error.empty()) status += " (" + error + ")";
        put_out(line.printed_path + ": " + status + "\n");
    }
    return success;
}

int check_files(const Options &options) {
    uint64_t failures = 0;
    for (const string &name : options.files) {
        FileOwner owner;
        FILE *f = open_input(name, owner);
        char *buffer = nullptr;
        size_t capacity = 0;
        for (;;) {
            errno = 0;
            ssize_t n = ::getline(&buffer, &capacity, f);
            if (n < 0) {
                std::free(buffer);
                buffer = nullptr;
                if (std::ferror(f)) throw std::runtime_error(os_error(errno));
                break;
            }
            string line(buffer, size_t(n));
            if (!valid_utf8(line)) {
                std::free(buffer);
                throw std::runtime_error("stream did not contain valid UTF-8");
            }
            std::optional<CheckLine> parsed;
            try { parsed = parse_check_line(std::move(line)); }
            catch (const std::exception &e) {
                put_err("b3sum: " + string(e.what()) + "\n");
                ++failures;
                continue;
            }
            if (!check_one(*parsed, options)) ++failures;
        }
    }
    if (failures) {
        put_err("b3sum: WARNING: " + std::to_string(failures) + " computed checksum" +
                (failures == 1 ? "" : "s") + " did NOT match\n");
        return 1;
    }
    return 0;
}

int run(Options options) {
    if (options.present[RAW] && options.files.size() > 1)
        throw std::runtime_error("Only one filename can be provided when using --raw");
    Mode mode = select_mode(options);
    if (options.files.empty()) options.files.emplace_back("-");
    if (options.present[CHECK]) return check_files(options);
    int result = 0;
    for (const string &path : options.files) {
        try {
            FileOwner owner;
            FILE *f = open_input(path, owner, options.present[KEYED]);
            digest::Hasher hasher(mode.key, mode.flags);
            add_file(hasher, f);
            write_digest(hasher.finish(), options, path);
        } catch (const std::exception &e) {
            put_err("b3sum: " + display_string(path) + ": " + e.what() + "\n");
            result = 1;
        }
    }
    return result;
}
}

int main(int argc, char **argv) {
    std::signal(SIGPIPE, SIG_IGN);
    string name = argc && argv[0] ? argv[0] : "executable";
    size_t slash = name.rfind('/');
    if (slash != string::npos) name.erase(0, slash + 1);
    name = display_string(name);
