inline bool nonempty_env(const char *name) {
    const char *value = std::getenv(name);
    return value && *value;
}

inline bool use_color(int fd) {
    if (nonempty_env("NO_COLOR")) return false;
    if (nonempty_env("CLICOLOR_FORCE")) return true;
    const char *value = std::getenv("CLICOLOR");
    if (value && std::string(value) == "0") return false;
    value = std::getenv("TERM");
    if (value && std::string(value) == "dumb") return false;
    return ::isatty(fd);
}

inline std::string paint(const std::string &s, const char *style) {
    return style + s + reset;
}

inline std::string option_words(const std::string &s) {
    std::string result;
    size_t i = 0;
    while (i < s.size()) {
        if (s[i] == '-' && (i == 0 || s[i - 1] == ' ' || s[i - 1] == '|')) {
            size_t end = i + 1;
            while (end < s.size() && ((s[end] >= 'a' && s[end] <= 'z') ||
                   (s[end] >= 'A' && s[end] <= 'Z') || s[end] == '-')) ++end;
            result += paint(s.substr(i, end - i), bold);
            i = end;
        } else result += s[i++];
    }
    return result;
}

inline std::string usage(const std::string &s, const std::string &program) {
    if (s.empty()) return s;
    std::string tail = s.substr(7 + program.size());
    if (tail.find("<FILE|") == std::string::npos) tail = option_words(tail);
    return paint("Usage:", heading) + " " + paint(program, bold) + tail;
}

inline std::string help(const std::string &s, const std::string &program) {
    std::string result;
    size_t position = 0;
    while (position < s.size()) {
        size_t end = s.find('\n', position);
        if (end == std::string::npos) end = s.size();
        std::string line = s.substr(position, end - position);
        if (line.compare(0, 7, "Usage: ") == 0) line = usage(line, program);
        else if (line == "Options:" || line == "Arguments:") line = paint(line, heading);
        else {
            size_t first = line.find_first_not_of(' ');
            if (first < 8 && line[first] == '-') {
                size_t last = line.find("  ", first);
                if (last == std::string::npos) last = line.size();
                line = option_words(line.substr(0, last)) + line.substr(last);
            }
        }
        result += line;
        if (end < s.size()) result += '\n';
        position = end + 1;
    }
    return result;
}

inline std::string quotes(const std::string &s, const std::vector<const char *> &styles) {
    std::string result;
    size_t pos = 0, n = 0;
    while (pos < s.size()) {
        size_t first = s.find('\'', pos);
        if (first == std::string::npos) break;
        size_t last = s.find('\'', first + 1);
        if (last == std::string::npos) break;
        result += s.substr(pos, first + 1 - pos);
        const char *style = styles[n < styles.size() ? n : styles.size() - 1];
        result += paint(s.substr(first + 1, last - first - 1), style);
        result += '\'';
        pos = last + 1;
        ++n;
    }
    result += s.substr(pos);
    return result;
}

