        if (end == std::string::npos) end = s.size();
        std::string line = s.substr(position, end - position);
        if (position == 0) line = quotes(line, bad_value ? std::vector<const char *>{yellow, bold} : std::vector<const char *>{yellow});
        else if (line.compare(0, 7, "  tip: ") == 0) {
