        } else if (line.compare(0, 2, "  ") == 0) {
            line = "  " + paint(line.substr(2), required ? green : yellow);
        }
        result += line;
        if (end < s.size()) result += '\n';
        position = end + 1;
    }
    return result;
}
}
#endif
